import {paths,tiers,slots,items,nodes,stats,level,skillRank,points,whyLearn,available} from './cultivation.js';
import {heroes} from './art.js';
import {maps} from './academy-core.js';
import {skillTitles} from './academy-learning.js';
export const tabs=['Sảnh hệ thống','Sảnh chiến đấu','Sảnh nâng cấp','Thông tin nhân vật','Hành trang vật phẩm'];
const img=(id,cls='')=>'<img class="'+cls+'" src="assets/'+id+'.webp" alt="">';
const act=(label,action,value='',disabled=false)=>'<button class="hub-action" data-action="'+action+'" data-value="'+value+'" '+(disabled?'disabled':'')+'>'+label+'</button>';
export function hubContent(tab,x,p,selected){
 const h=p.hero,l=level(x),power=stats(x,h),rank=skillRank(x);
 const mark='<div class="hub-kicker">HỌC VIỆN AN HÒA · CẤP '+l+'</div>';
 const intro=msg=>mark+'<h1>'+tabs[tab]+'</h1><p class="hub-lead">'+msg+'</p>';
 if(tab===0)return intro('Chọn việc em muốn làm.')+'<div class="hub-welcome">'+img(heroes[h])+'<div><small>HỌC VIÊN · '+paths[h]+'</small><h2>'+skillTitles[h]+'</h2><p>Cấp '+l+' · '+x.clears.length+' / 15 vòng đã thắng</p><progress value="'+x.xp%50+'" max="50"></progress><small>'+(l===20?'Đã đạt cấp tối đa':(50-x.xp%50)+' kinh nghiệm nữa lên cấp')+'</small>'+act('Chọn vòng chơi →','tab',1)+'</div></div><div class="hub-links">'+[2,3,4].map((t,i)=>act(tabs[t]+'<small>'+[points(x)+' điểm rễ còn lại','Kỹ năng bậc '+rank,x.bag.length+' vật phẩm'][i]+'</small>','tab',t)).join('')+'</div>';
 if(tab===1){const m=maps[selected];return intro('Mỗi bản đồ có ba vòng. Thắng một vòng để mở vòng kế tiếp.')+'<div class="map-selector">'+maps.map((v,i)=>act((i+1)+'. '+v.name+(i>p.unlocked?' · Chưa mở':''),'map',i,i>p.unlocked)).join('')+'</div><div class="round-cover" style="background-image:linear-gradient(90deg,#142b30ee,transparent),url(assets/'+m.background+'.webp)"><small>BẢN ĐỒ '+(selected+1)+'</small><h2>'+m.name+'</h2></div><div class="hub-cards">'+tiers.map((t,i)=>{const done=x.clears.includes(selected+'-'+i),ok=available(x,p.unlocked,selected,i);return '<article><small>VÒNG '+(i+1)+(done?' · ĐÃ THẮNG':'')+'</small><h3>'+t+'</h3><p>Hai đợt: '+(300+100*i)+' và '+(400+i*150)+' HP.</p><p>'+['Đối thủ phản công sau mỗi lượt.','Màn sương dày hơn, cần nhiều phép hơn.','Đòn phản công mạnh thêm 1 sinh lực.'][i]+'</p>'+act(ok?(done?'Chơi lại':'Vào vòng →'):'Thắng vòng '+tiers[i-1],'fight',i,!ok)+'</article>';}).join('')+'</div>';}
 if(tab===2)return intro('Mỗi cấp có một điểm rễ. Mở gốc rồi chọn nhánh con; chỉ nhánh của trường phái đang dùng cộng sức mạnh.')+'<p class="hub-badge">◇ '+points(x)+' điểm rễ · Đang dùng '+paths[h]+'</p><div class="root-tree"><div class="tree-origin">✦ Linh căn</div>'+paths.map((name,k)=>'<section class="tree-branch '+(k===h?'current':'')+'"><h3>'+name+'</h3><div class="node-pair">'+nodes.filter(n=>n.h===k).map(n=>{const reason=whyLearn(x,n);return '<article class="root-node '+(n.parent?'child':'trunk')+'"><small>'+(n.parent?'RỄ PHỤ':'RỄ CHÍNH')+'</small><b>'+n.name+' · '+(x.ranks[n.id]||0)+'/3</b><small>Mỗi bậc: '+(n.atk?'+'+n.atk+' công ':'')+(n.hp?'+'+n.hp+' sinh lực':'')+'</small>'+act(reason||'Nâng · 1 điểm','learn',n.id,!!reason)+'</article>';}).join('')+'</div></section>').join('')+'</div>';
 if(tab===3)return intro('Xem sức mạnh thực tế và chọn trường phái cho trận tiếp theo.')+'<div class="hub-welcome">'+img(heroes[h])+'<div><h2>'+paths[h]+'</h2><p>Cấp '+l+' · '+x.xp+' kinh nghiệm</p><p>Công '+power.atk+' · Sinh lực '+power.hp+'</p><b>'+skillTitles[h]+' · Bậc '+rank+'</b><p>'+(rank<5?'Kỹ năng tự lên bậc tại cấp '+(rank*3+1)+'.':'Kỹ năng đã đạt bậc tối đa.')+'</p></div></div><div class="hub-links">'+paths.map((name,k)=>act(name+(h===k?' · Đang dùng':''),'hero',k,h===k)).join('')+'</div><h3>Đang trang bị</h3><p>'+Object.entries(slots).map(([slot,name])=>name+': '+(items.find(i=>i.id===x.worn[slot])?.name||'Trống')).join(' · ')+'</p>'+act('Mở hành trang →','tab',4);
 return intro('Chạm vào trang bị để dùng hoặc tháo. Mỗi vị trí chỉ dùng một món.')+'<p class="hub-badge">Công '+power.atk+' · Sinh lực '+power.hp+'</p><div class="hub-cards">'+x.bag.map(id=>{const i=items.find(i=>i.id===id),on=x.worn[i.slot]===id;return '<article class="'+(on?'equipped':'')+'"><small>'+slots[i.slot]+' · CẤP '+i.level+'</small><h3>'+i.name+'</h3><p>'+(i.atk?'+'+i.atk+' công ':'')+(i.hp?'+'+i.hp+' sinh lực':'')+'</p>'+act(on?'Tháo trang bị':l<i.level?'Cần cấp '+i.level:'Trang bị','equip',id,l<i.level)+'</article>';}).join('')+'</div>';
}
